Следующий код создаст бота Discord, который использует Discord.js v14 и имеет одну слэш-команду для банирования:

1. Сначала необходимо установить пакеты:

```
npm install discord.js @discordjs/rest discord.js-commando
```

2. Создайте файл `config.json` и добавьте в него следующие настройки:

```json
{
  "token": "YOUR_DISCORD_BOT_TOKEN",
  "clientId": "YOUR_CLIENT_ID",
  "guildId": "YOUR_GUILD_ID"
}
```

3. Создайте файл `commands/banCommand.js` и добавьте в него следующий код для создания слэш-команды бан:

```javascript
const { SlashCommandBuilder } = require('discord.js-commando');

module.exports = new SlashCommandBuilder()
  .setName('ban')
  .setDescription('Bans a user from the server')
  .addUserOption(option =>
    option.setName('user')
      .setDescription('The user to ban')
      .setRequired(true)
  )
  .addStringOption(option =>
    option.setName('reason')
      .setDescription('The reason for the ban')
      .setRequired(true)
  );
```

4. В файле `index.js` добавьте следующий код для настройки бота:

```javascript
const { CommandoClient } = require('discord.js-commando');
const { Intents } = require('discord.js');
const { config } = require('./config.json');

const client = new CommandoClient({
  commandPrefix: '/',
  type: CommandoClient.type.GUILD_ONLY,
  intents: [
    Intents.FLAGS.GUILDS,
    Intents.FLAGS.GUILD_MESSAGES,
    Intents.FLAGS.GUILD_MEMBERS,
  ],
});

client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}`);
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const command = client.commands.get(interaction.commandName);

  if (!command) return;

  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    await interaction.reply({ content: 'There was an error while executing this command!', ephemeral: true });
  }
});

module.exports = client;
```

5. В файле `index.js`, добавьте следующий код для регистрации слэш-команды:

```javascript
const { REST } = require('@discordjs/rest');
const { Routes } = require('discord-api-types/v9');
const { config } = require('./config.json');

const commands = [];
const commandFiles = require.context('./commands', true, /\.js$/);

commandFiles.keys().forEach((key) => commands.push(commandFiles(key).default));

const rest = new REST({ version: '9' }).setToken(config.token);

(async () => {
  try {
    await rest.put(
      Routes.applicationGuildCommands(config.clientId, config.guildId),
      { body: commands },
    );

    console.log('Successfully registered application commands.');
  } catch (error) {
    console.error(error);
  }
})();

require('./commands/banCommand');
```

6. Скопируйте `index.js` и сохраните его в корневую папку вашего проекта.

7. Запустите ваш бот, запустив `node index.js`.

Теперь ваш бот сможет получать команду бан в виде слэш-команды! 

