```c++
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    std::string word_to_search;
    std::cout << "Enter the word to search: ";
    std::cin >> word_to_search;

    std::string filename;
    std::cout << "Enter the filename: ";
    std::cin >> filename;

    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return 1;
    }

