    std::size_t count = 0;

    while (getline(file, line)) {
        std::size_t pos = 0;
        while ((pos = line.find(word_to_search, pos)) != std::string::npos) {
            count++;
            pos += word_to_search.length();
        }
    }

    file.close();

    std::cout << "Number of occurrences of \"" << word_to_search << "\" in " << filename << ": " << count << std::endl;

    return 0;
}
